using System;using System.IO;using System.Text;using PandaLauncher;
class SpotifyDetection {
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("OK : "+label);}
 static void Main(string[] args){string alias=@"C:\Users\Test\AppData\Local\Microsoft\WindowsApps\Spotify.exe",family="SpotifyAB.SpotifyMusic_test",target=@"C:\Program Files\WindowsApps\Spotify_v1\SpotifyMigrator.exe";byte[] strings=Encoding.Unicode.GetBytes(family+"\0"+family+"!Spotify\0"+target+"\0"+"0\0");var data=new byte[12+strings.Length];Buffer.BlockCopy(BitConverter.GetBytes(0x8000001bu),0,data,0,4);Buffer.BlockCopy(BitConverter.GetBytes((ushort)(strings.Length+4)),0,data,4,2);Buffer.BlockCopy(BitConverter.GetBytes(3u),0,data,8,4);Buffer.BlockCopy(strings,0,data,12,strings.Length);var identity=ExecutionIdentity.Parse(alias,data,data.Length);
 Check(identity.Family==family,"identité du paquet lue depuis l’alias");Check(identity.Matches(@"C:\Program Files\WindowsApps\Spotify_v2\Spotify.exe",family),"processus du même paquet reconnu malgré un autre chemin/version");Check(!identity.Matches(@"D:\Autre\Spotify.exe",null),"homonyme classique rejeté");Check(!identity.Matches(@"D:\Autre\Spotify.exe","AutrePaquet"),"autre paquet rejeté");Check(!identity.Matches(@"C:\Program Files\WindowsApps\Spotify_v1\SpotifyLauncher.exe",family),"autre composant du paquet rejeté");Check(ExecutionIdentity.Parse(alias,data,11).Family==null,"métadonnées tronquées ignorées");data[0]=0;Check(ExecutionIdentity.Parse(alias,data,data.Length).Family==null,"autre type de lien non interprété comme un alias");
 if(args.Length>0){var entry=new Entry{Name="Spotify",Target=args[0]};var resolved=Shortcuts.Resolve(entry);var actual=ExecutionIdentity.Read(resolved.Target);Console.WriteLine("Paquet identifié : "+actual.Family);var state=RuntimeProbe.Read(entry);Check(state.Kind==RuntimeKind.Running,"Spotify actuellement ouvert reconnu sans le relancer");Console.WriteLine(state.Text);}
 }
}
